-- Revisao automatica por hash. Nao e aprovacao humana.
create table if not exists canonical_auto_review (
  path text primary key,
  veredito text not null check (veredito in ('CONFERIDO','DIVERGENTE','AUSENTE','SEGREDO')),
  blob_esperado text not null,
  blob_encontrado text not null default '',
  regra text not null,
  revisor text not null default 'migrar-com-revisao.py'
    check (revisor = 'migrar-com-revisao.py'),
  revisao_humana boolean not null default false check (revisao_humana = false)
);
on conflict (path) do nothing;
